const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountJourneyMap(host,farm,crop){let active=0,frame=0,position=0;const same=farm.crop?.startsWith(crop.name),annual=crop.name==='Arroz',origin=farm.crop||'Cultivo sin confirmar';const nodes=[{icon:'🌳',title:origin,period:'HOY',text:'Este es el cultivo registrado en tu escenario. Confirma que corresponde a la finca.',action:'Conocer suelo, agua e historial.'},{icon:crop.symbol,title:crop.name,period:annual?'LOTE ANUAL PROPUESTO':'PRÓXIMAS CAMPAÑAS',text:same?'La propuesta es mantener tu cultivo y evaluar ajustes de manejo.':annual?'El arroz se evalúa en un lote anual separado. Los frutales no se sustituyen automáticamente.':'El cambio a '+crop.name+' sería una reconversión de largo plazo. Todavía no tiene viabilidad ni fecha confirmadas.',action:'Revisar condiciones y costos con tu técnico.'},{icon:crop.symbol,title:crop.name,period:annual?'CIERRE DE CAMPAÑA':'CONTINUIDAD',text:annual?'Después de la cosecha se deben revisar los resultados antes de elegir otro cultivo. Aún no hay una siguiente rotación validada.':'La plantación continúa en el tiempo. No se calcula todavía la fecha de cosecha ni el ingreso esperado.',action:'Registrar resultados antes de decidir el siguiente paso.'}];
host.innerHTML='<section class="quest-map reference-map"><div class="quest-caption"><span>'+ (same?'CONSERVAR Y ADAPTAR':annual?'CAMPAÑA EN LOTE SEPARADO':'ALTERNATIVA DE RECONVERSIÓN')+'</span><h3>'+esc(origin)+' → '+crop.name+'</h3><p>Recorrido propuesto · fechas y aptitud por validar</p></div><div class="reference-land"><svg viewBox="0 0 1000 420" aria-hidden="true"><defs><linearGradient id="ref-sky" x2="0" y2="1"><stop stop-color="#b7dfcf"/><stop offset="1" stop-color="#f1f5d6"/></linearGradient></defs><rect width="1000" height="420" fill="url(#ref-sky)"/><circle cx="865" cy="70" r="57" fill="#ffe19466"/><circle cx="865" cy="70" r="32" fill="#f7c75e"/><path d="M0 210Q170 110 350 190T700 155T1000 180V420H0Z" fill="#a7c887"/><path d="M0 290Q230 200 460 290T1000 240V420H0Z" fill="#75a867"/><path d="M0 370Q240 320 470 380T1000 340" fill="none" stroke="#79bdc7" stroke-width="28"/><path class="quest-trail" d="M0 370Q240 320 470 380T1000 340" fill="none" stroke="#ddf4ef" stroke-width="3" stroke-dasharray="9 19"/><g fill="#fff" opacity=".8" class="ref-cloud"><ellipse cx="140" cy="70" rx="55" ry="17"/><ellipse cx="160" cy="55" rx="33" ry="22"/></g><g font-size="37"><text x="45" y="240">🌳</text><text x="495" y="160">🌳</text><text x="920" y="295">🌳</text></g><path class="reference-road" d="M130 235C260 235 300 120 420 180S570 340 660 270S790 150 870 185" fill="none" stroke="#b38a4c" stroke-width="43"/><path d="M130 235C260 235 300 120 420 180S570 340 660 270S790 150 870 185" fill="none" stroke="#e4c994" stroke-width="34"/><path class="quest-trail" d="M130 235C260 235 300 120 420 180S570 340 660 270S790 150 870 185" fill="none" stroke="#fff8df" stroke-width="3" stroke-dasharray="8 14"/><g class="reference-tractor"><text text-anchor="middle" y="-55" font-size="42">🚜</text></g></svg><div class="reference-stops">'+nodes.map((n,i)=>'<button data-stop="'+i+'"><span>'+n.icon+'</span><small>'+n.period+'</small><strong>'+esc(n.title)+'</strong></button>').join('')+'</div></div><div class="quest-controls"><button class="quest-back">← Anterior</button><span class="quest-progress"></span><button class="quest-forward">Siguiente cultivo →</button></div><div class="reference-explanation"><div class="quest-info" aria-live="polite"></div><aside><small>ANTES DE DECIDIR</small><h4>¿Qué falta comprobar?</h4><p>💧 Agua disponible para la campaña</p><p>🌱 Suelo y variedad compatibles</p><p>📋 Costos y comprador</p><strong>Sin ganancias ni ahorros calculados.</strong></aside></div><p class="quest-disclaimer">Ilustración conceptual. Estas etapas no constituyen una rotación agronómica aprobada ni un calendario de siembra.</p></section>';
const road=host.querySelector('.reference-road'),length=road.getTotalLength(),fractions=[0,.5,1],tractor=host.querySelector('.reference-tractor');host.querySelectorAll('[data-stop]').forEach((el,i)=>{const p=road.getPointAtLength(length*fractions[i]);el.style.left=p.x/10+'%';el.style.top=p.y/4.2+'%';el.onclick=()=>{active=i;update()};});
function move(){cancelAnimationFrame(frame);const target=length*fractions[active],from=position,start=performance.now(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function tick(t){if(!host.isConnected)return;const k=reduced?1:Math.min(1,(t-start)/850);position=from+(target-from)*(1-Math.pow(1-k,3));const p=road.getPointAtLength(position);tractor.setAttribute('transform','translate('+p.x+' '+p.y+')');if(k<1)frame=requestAnimationFrame(tick);}frame=requestAnimationFrame(tick);}
function update(){host.querySelectorAll('[data-stop]').forEach(el=>el.setAttribute('aria-current',Number(el.dataset.stop)===active?'step':'false'));const n=nodes[active];host.querySelector('.quest-info').innerHTML='<small>'+n.period+'</small><h4>'+n.icon+' '+esc(n.title)+'</h4><p>'+esc(n.text)+'</p><div class="reference-simple"><b>Tu siguiente paso</b><p>'+n.action+'</p></div>';host.querySelector('.quest-back').disabled=active===0;host.querySelector('.quest-forward').disabled=active===2;host.querySelector('.quest-progress').textContent=(active+1)+' / 3';move();}
host.querySelector('.quest-back').onclick=()=>{active=Math.max(0,active-1);update()};host.querySelector('.quest-forward').onclick=()=>{active=Math.min(2,active+1);update()};update();}
